import{_ as t,o as e,c as n,a3 as r}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Promotions","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/promotions.md","filePath":"user/center/promotions.md"}'),s={name:"user/center/promotions.md"};function a(i,o,c,l,h,p){return e(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="promotions" tabindex="-1">Promotions <a class="header-anchor" href="#promotions" aria-label="Permalink to &quot;Promotions&quot;">​</a></h1><p>You need the <strong>promotions</strong> permission. Promotions give clients a discount on your services only.</p><h2 id="creating-one" tabindex="-1">Creating one <a class="header-anchor" href="#creating-one" aria-label="Permalink to &quot;Creating one&quot;">​</a></h2><p><strong>Promotions → New.</strong> It starts as a <strong>draft</strong>. Choose:</p><ul><li>the discount: <strong>percentage</strong>, <strong>fixed amount</strong> or <strong>fixed price</strong></li><li>an optional <strong>maximum discount</strong> and <strong>minimum spend</strong></li><li>the <strong>dates</strong> and an optional <strong>weekly schedule</strong></li><li>which services it <strong>targets</strong></li><li>whether it needs a <strong>coupon code</strong></li></ul><p>Then <strong>Activate</strong>. You can <strong>pause</strong> and resume, or <strong>archive</strong> it. Centers pay for their own promotions; the platform can run its own separately.</p><p>Once a promotion has been used, its discount and targets are locked. Archive it and create a new one to change them.</p><h2 id="coupons" tabindex="-1">Coupons <a class="header-anchor" href="#coupons" aria-label="Permalink to &quot;Coupons&quot;">​</a></h2><p>Add coupons one by one, or <strong>generate</strong> a batch. Codes are saved in capitals. Set a total limit and a per-client limit.</p><h2 id="what-clients-see" tabindex="-1">What clients see <a class="header-anchor" href="#what-clients-see" aria-label="Permalink to &quot;What clients see&quot;">​</a></h2><p>While an automatic promotion is running, your service shows the <strong>original</strong> and <strong>discounted</strong> starting price with a badge such as &quot;-15%&quot;. Promotions with a minimum spend, or that apply to the whole order, are applied at checkout and not shown on the service.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p>Open <strong>Redemptions</strong> to see where a promotion was used.</p>',13)])])}const g=t(s,[["render",a]]);export{u as __pageData,g as default};
